 const say=useWords(),[request,setRequest]=useState(initialGoal),[draft,setDraft]=useState<TaskSuggestion|null>(null),[backLocked,setBackLocked]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState('');
